import {useState} from 'react';
import {createRoot} from 'react-dom/client';
import {ConfirmationProvider} from '../../src/Confirmation';
import {setLanguage} from '../../src/i18n';
import TaskCreationGuide from '../../src/TaskCreationGuide';
import {SpaceProjectRelations} from '../../src/ProjectBindingPlanner';
import type {Employee,Space,TaskDraft,SpaceAPI} from '../../src/workforce-types';
import '../../src/shadcn.css';import '../../src/styles.css';import '../../src/workforce.css';
const params=new URLSearchParams(location.search),en=params.has('en');setLanguage(en?'en':'zh-CN');if(params.has('dark'))document.documentElement.dataset.theme='dark';
const stamp=new Date().toISOString(),projects=[{id:'web',name:'Web',path:'/test/web',createdAt:stamp},{id:'api',name:'API',type:'ssh' as const,connectionId:'connection',path:'/srv/api',createdAt:stamp}];
const employees=[{id:'engineer',name:'Engineer',status:'ready',requirements:[],skills:[],responsibilities:'Build and verify',methods:'Verify',deliverables:'Code'}] as unknown as Employee[];
let space:Space={id:'space',name:'Delivery',purpose:'Integrated delivery',revision:1,createdAt:stamp,updatedAt:stamp,projectIds:['web','api'],members:[{employeeId:'engineer',assignment:'Implementation',projectIds:['web','api']}],projectContext:{roles:[{projectId:'web',responsibility:'Web client'}],relations:[{sourceProjectId:'web',targetProjectId:'api',kind:'api',description:'Use /v1; verify connectivity at execution'}]}};
let draft:TaskDraft={id:'draft',spaceId:'space',discussionId:null,revision:2,status:'needs-input',source:[],messages:[],assessment:{ready:false,revision:2,summary:'Review project assignments',missing:[],question:null},value:{name:'Delivery',goal:'Integrate Web and API',packages:['client','checks'].map((id,index)=>({id,title:index?'Verify client':'Build client',instruction:'Implement and verify the assigned scope',ownerId:'engineer',mode:'work',projectId:null,dependencies:[],deliverables:'Code and evidence',acceptance:'Contract tests pass',verification:'Run contract tests',documentRefs:[]}))}};
if(params.has('dependent')){for(const p of draft.value.packages){p.projectId='web';p.projectBinding={responsibility:'Web client',confirmed:true,relations:[{targetProjectId:'api',kind:'api',description:'Use /v1'}]};}draft.value.packages[1].dependencies=['client'];}
const calls:any[]=[];
const api={createTaskDraft:async()=>structuredClone(draft),saveTaskDraft:async(input:any)=>{draft={...draft,value:structuredClone(input.value),revision:draft.revision+1,status:'needs-input',assessment:undefined};calls.push({action:'saveDraft',input});return structuredClone(draft);},checkTaskDraft:async(input:any)=>{calls.push({action:'check',input});draft.status='ready';draft.revision++;draft.assessment={revision:draft.revision,summary:'Draft checked',missing:[],ready:true,question:null};return structuredClone(draft);},saveProjectContext:async(input:any)=>{if(input.expectedRevision!==space.revision)throw Error('空间已更新');space={...space,revision:space.revision+1,projectContext:input.value};calls.push({action:'context',input});return structuredClone(space);},snapshot:async()=>({spaces:[space],documents:[],requests:[],plans:[],taskDrafts:[draft]}),createGuidedPlan:async(input:any)=>{calls.push({action:'create',input});return {id:'plan',revision:1,name:'Delivery',status:'draft',packages:draft.value.packages.map(definition=>({id:definition.id,definition}))};},controlPlan:async(input:any)=>{calls.push({action:'start',input});return {id:'plan'};},guideTask:async()=>{throw Error('The model should not be called for node edits');}} as unknown as SpaceAPI;
if(params.has('guided')){
 draft.relationGuide={requestKey:'relationships',spaceRevision:1,nodes:draft.value.packages.map(p=>({packageId:p.id,title:p.title,reason:'Review the project suggested from your discussion.',fields:[{name:'projectId',label:'Execution project',type:'select',required:true,options:[{value:'web',label:'Web (Recommended)'},{value:'api',label:'API'}]},{name:'responsibility',label:'Project responsibility',type:'textarea',required:true},{name:'relationshipMode',label:'Collaboration',type:'select',options:[{value:'independent',label:'Independent'},{value:'related',label:'Use another project'}]},{name:'description0',label:'Handoff agreement',type:'textarea',required:true,visibleWhen:{field:'relationshipMode',equals:'related'}}],prefill:{projectId:'web',responsibility:'Web client',relationshipMode:'independent'}}))};
 api.answerTaskRelations=async input=>{calls.push({action:'answerRelations',input});if(input.answers.responsibility==='simulate failure')throw Error('Temporary save failure');draft.value.packages=draft.value.packages.map(p=>p.id===input.packageId?{...p,projectId:String(input.answers.projectId),projectBinding:{responsibility:String(input.answers.responsibility),relations:[],confirmed:true}}:p);draft.revision++;draft.relationGuide!.nodes=draft.relationGuide!.nodes.filter(n=>n.packageId!==input.packageId);if(!draft.relationGuide!.nodes.length){draft.relationGuide=null;draft.status='ready';}return structuredClone(draft);};
 api.guideTask=async input=>{calls.push({action:'refine',input});draft.revision++;return structuredClone(draft);};
}
window.desktop={spaces:api} as any;(window as any).relationQA={calls,getSpace:()=>space,getDraft:()=>draft};
function QA(){const [current,setCurrent]=useState(space),[closed,setClosed]=useState(false);return <ConfirmationProvider><main className="wf" style={{padding:24,maxWidth:1100,margin:'auto'}}>{closed?<h1>Plan created</h1>:params.has('space')?<SpaceProjectRelations space={current} projects={projects} refresh={async()=>setCurrent({...space})}/>:<TaskCreationGuide space={current} employees={employees} projects={projects} catalog={{providers:[]}} close={()=>setClosed(true)} created={()=>{}} refresh={async()=>setCurrent({...space})}/>}</main></ConfirmationProvider>;}
createRoot(document.getElementById('root')!).render(<QA/>);
